"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[89],{89:(e,t,n)=>{n.d(t,{Bg:()=>o,gt:()=>i,lv:()=>s,qv:()=>r});let i=[{label:"Home",href:"/"},{label:"About",href:"/about"},{label:"Process",href:"/process"},{label:"Industries",href:"/industries"},{label:"Career",href:"/careers"},{label:"Contact",href:"/contact"}],o=[{slug:"cloud-solutions",title:"Cloud Solutions",icon:"cloud",short:"Move confidently to the cloud with secure architecture, migration planning, infrastructure optimization, and ongoing management.",narrative:["Cloud adoption is no longer a question of if, but how — and how well it's planned determines whether it reduces cost and risk or simply relocates old problems onto new infrastructure.","At Frontier One Technology, cloud engagements begin with a clear-eyed assessment of your current environment: what you're running, what it costs, what's fragile, and what's actually ready to move. From there, we design a secure, right-sized architecture — not a default, one-size-fits-all template — and plan the migration in phases that protect business continuity.","Once you're in the cloud, our work continues. We optimize spend, tighten access controls, build in resilience and disaster recovery, and provide ongoing management so your infrastructure keeps pace with your business instead of becoming its own maintenance burden."],delivers:["Cloud readiness assessment & migration planning","Secure architecture design","Infrastructure cost optimization","Disaster recovery & resilience planning","Ongoing cloud management & support"],focus:["AWS","Microsoft Azure","Google Cloud","Hybrid Cloud","Disaster Recovery","Cloud-Native"]},{slug:"software-engineering",title:"Software Engineering",icon:"code",short:"Custom web applications, enterprise software, APIs, internal platforms, and scalable business applications built around your goals.",narrative:["Off-the-shelf software works — until it doesn't fit how your business actually operates. Frontier One Technology builds custom applications and platforms designed around your real workflows, not the other way around.","Our engineering team works closely with your stakeholders to understand the business problem before writing a single line of code. We design maintainable architectures, build with modern frameworks, and integrate cleanly with the systems you already rely on — whether that's a customer-facing web application, an internal operations platform, or the APIs that connect them.","Every engagement follows disciplined engineering practices — code review, automated testing, and clear documentation — so what we build remains easy for your team (or ours) to extend for years, not just months."],delivers:["Custom web & enterprise application development","API design & integration","Internal tools & operational platforms","Legacy system modernization","Scalable, maintainable architecture"],focus:["Web Applications","Enterprise Software","APIs","Microservices","Responsive Platforms"]},{slug:"cybersecurity",title:"Cybersecurity",icon:"shield",short:"Protect your business through identity management, access controls, security assessments, compliance support, and proactive monitoring.",narrative:["Security can't be an afterthought bolted on before launch — it has to be part of how a system is designed from day one. That's the principle behind every security engagement we run.","Frontier One Technology helps organizations strengthen their security posture through practical, prioritized action: assessing where real risk exists, implementing modern identity and access management, and closing the gaps that matter most rather than chasing every theoretical vulnerability.","For regulated industries, we help translate compliance requirements into working controls — not just documentation — and we support ongoing monitoring so new risks are caught early rather than discovered after an incident."],delivers:["Security assessments & risk reviews","Identity & Access Management (IAM)","Access control & Zero Trust implementation","Compliance support","Proactive monitoring & threat detection"],focus:["IAM","SSO","MFA","Zero Trust","SIEM","Compliance Frameworks"]},{slug:"data-analytics",title:"Data & Analytics",icon:"chart",short:"Transform business data into meaningful insights with reporting, dashboards, automation, and modern analytics solutions.",narrative:["Most organizations aren't short on data — they're short on usable insight. Frontier One Technology bridges that gap by turning scattered, siloed data into dashboards and reporting your team can actually act on.","We start by mapping where your data lives and how it flows, then design pipelines and reporting layers that consolidate it into a single, reliable source of truth. From there, we build dashboards and automated reporting tailored to the decisions your business actually needs to make — not generic, one-size-fits-all metrics.","The result is faster, more confident decision-making, with less manual reporting work for your team."],delivers:["Data pipeline design & automation","Reporting & dashboard development","Business intelligence solutions","Data integration across systems","Analytics strategy & consulting"],focus:["Power BI","Snowflake","Data Warehousing","ETL Pipelines","Real-Time Analytics","Governance"]},{slug:"devops-automation",title:"DevOps & Automation",icon:"pipeline",short:"Accelerate software delivery with CI/CD pipelines, infrastructure automation, containerization, and cloud-native deployment strategies.",narrative:["Slow, manual releases create risk and drain engineering time that should be spent building. Frontier One Technology helps organizations modernize how software gets delivered — safely and quickly.","We design CI/CD pipelines that automate testing and deployment, containerize applications for consistency across environments, and codify infrastructure so environments are reproducible and auditable rather than manually configured.","The outcome is a delivery process your engineering team can trust: faster releases, fewer deployment surprises, and infrastructure that scales cleanly as your product grows."],delivers:["CI/CD pipeline design & implementation","Infrastructure as Code","Containerization (Docker/Kubernetes)","Cloud-native deployment strategy","Release process automation"],focus:["Docker","Kubernetes","Terraform","Jenkins","GitHub Actions","Monitoring"]},{slug:"artificial-intelligence",title:"Artificial Intelligence",icon:"sparks",short:"Leverage intelligent automation and AI-powered solutions to improve customer experiences, streamline operations, and support faster decision-making.",narrative:["AI delivers real business value when it's applied to a specific, well-defined problem — not when it's added for its own sake. Frontier One Technology approaches AI the same way we approach every technology decision: starting with the business outcome, not the buzzword.","We help organizations identify where intelligent automation can meaningfully reduce manual work, where AI-assisted tools can improve customer-facing experiences, and where predictive or analytical models can support faster, better-informed decisions.","Every AI implementation we deliver is built with the same engineering discipline as the rest of our work — secure, explainable where it matters, and integrated cleanly into your existing systems and workflows."],delivers:["Intelligent process automation","AI-assisted customer experience tools","Predictive analytics","Workflow & document automation","AI strategy & integration consulting"],focus:["AI Automation","Conversational AI","Document Processing","Predictive Analytics","Recommendations"]}],r=[{n:"01",title:"Discover",body:"We begin by understanding your business, current technology landscape, challenges, and long-term goals. Every successful project starts with asking the right questions."},{n:"02",title:"Assess",body:"Our team evaluates your existing infrastructure, applications, workflows, and security posture to identify opportunities for improvement and potential risks before development begins."},{n:"03",title:"Strategize",body:"Based on our findings, we create a practical roadmap that outlines the recommended technologies, project milestones, timelines, and implementation strategy tailored to your organization."},{n:"04",title:"Design",body:"We design scalable architectures, intuitive user experiences, and secure technical solutions that are built to support both your current operations and future growth."},{n:"05",title:"Develop",body:"Our engineers build, integrate, and configure technology solutions using modern development practices while maintaining high standards for quality, performance, and security."},{n:"06",title:"Validate",body:"Before deployment, every solution undergoes comprehensive testing, performance validation, security reviews, and quality assurance to ensure it meets business and technical expectations."},{n:"07",title:"Deploy",body:"We carefully implement the solution with minimal disruption, ensuring a smooth transition through structured deployment, documentation, and knowledge transfer."},{n:"08",title:"Support & Evolve",body:"Technology continues to evolve, and so do we. After deployment, we provide ongoing support, optimization, maintenance, and strategic guidance to help your business adapt and grow with confidence."}],s=[{year:"2020",title:"The Idea Started",body:"The journey began with a simple observation: businesses were adopting technology faster than ever, but many still struggled with practical implementation, security, and long-term scalability."},{year:"2021",title:"Building Technical Direction",body:"We started shaping our focus around software development, cloud solutions, cybersecurity, and business technology support."},{year:"2022",title:"Expanding Knowledge & Capabilities",body:"Our expertise grew across modern platforms, automation, data solutions, and enterprise technology environments."},{year:"2023",title:"From Skills to Solutions",body:"We began turning technical knowledge into structured service offerings designed to solve real business problems."},{year:"2024",title:"Creating a Strong Service Model",body:"Our approach became more defined: understand the business first, design practical solutions, and provide support beyond deployment."},{year:"2025",title:"Preparing for Growth",body:"We expanded our vision into a full technology consulting model, focusing on cloud, AI, cybersecurity, data, DevOps, and enterprise IT services."},{year:"2026",title:"Frontier One Technology",body:"Frontier One Technology was built with a clear mission: to deliver secure, scalable, and business-focused technology solutions that create long-term value."}]}}]);